import re
T=[]
_NUM=re.compile(r'\d+(?:[.,]\d+)*')
def add(es,en,pt):
    n=_NUM.findall(es)
    assert n==_NUM.findall(en)==_NUM.findall(pt), ('orden de números distinto',es,en,pt)
    T.append((_NUM.sub('{n}',es),_NUM.sub('{n}',en),_NUM.sub('{n}',pt)))
